CREATE TABLE IF NOT EXISTS site_settings (id INTEGER PRIMARY KEY, site_name TEXT NOT NULL, site_description TEXT NOT NULL, logo_url TEXT NOT NULL, avatar_url TEXT NOT NULL, verification_badge_url TEXT NOT NULL DEFAULT '', primary_color TEXT NOT NULL, public_url TEXT NOT NULL, allow_register INTEGER NOT NULL DEFAULT 1, require_email_verification INTEGER NOT NULL DEFAULT 0, post_review_required INTEGER NOT NULL DEFAULT 1, allowed_email_domains TEXT NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS captcha_settings (id INTEGER PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 0, provider TEXT NOT NULL DEFAULT 'gt4', site_key TEXT NOT NULL, endpoint TEXT NOT NULL, secret_ciphertext TEXT NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS smtp_settings (id INTEGER PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 0, host TEXT NOT NULL, port INTEGER NOT NULL DEFAULT 587, username TEXT NOT NULL, password_ciphertext TEXT NOT NULL, from_email TEXT NOT NULL, from_name TEXT NOT NULL, tls_mode TEXT NOT NULL DEFAULT 'starttls', updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, custom_uid TEXT COLLATE NOCASE UNIQUE, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, display_name TEXT NOT NULL, avatar_url TEXT NOT NULL, cover_url TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT 'user', status TEXT NOT NULL DEFAULT 'active', roblox_name TEXT NOT NULL DEFAULT '', roblox_id TEXT NOT NULL DEFAULT '', roblox_verified INTEGER NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS user_follows (follower_id INTEGER NOT NULL, followed_id INTEGER NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (follower_id, followed_id));
CREATE TABLE IF NOT EXISTS user_progress (user_id INTEGER PRIMARY KEY, experience INTEGER NOT NULL DEFAULT 0, total_checkins INTEGER NOT NULL DEFAULT 0, current_streak INTEGER NOT NULL DEFAULT 0, longest_streak INTEGER NOT NULL DEFAULT 0, last_checkin_date DATE, updated_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS user_checkins (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, checkin_date DATE NOT NULL, experience_awarded INTEGER NOT NULL, streak INTEGER NOT NULL, created_at DATETIME NOT NULL, UNIQUE(user_id, checkin_date), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS badges (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL, icon TEXT NOT NULL DEFAULT 'badge', color TEXT NOT NULL DEFAULT '#1d9bf0', created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS user_badges (user_id INTEGER NOT NULL, badge_id INTEGER NOT NULL, awarded_at DATETIME NOT NULL, PRIMARY KEY(user_id, badge_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(badge_id) REFERENCES badges(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS auth_sessions (token_hash BLOB PRIMARY KEY, user_id INTEGER NOT NULL, expires_at DATETIME NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS password_resets (token_hash BLOB PRIMARY KEY, user_id INTEGER NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME, created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS boards (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL, icon TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS posts (id INTEGER PRIMARY KEY AUTOINCREMENT, board_id INTEGER NOT NULL, author_id INTEGER NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'published', pinned INTEGER NOT NULL DEFAULT 0, featured INTEGER NOT NULL DEFAULT 0, views INTEGER NOT NULL DEFAULT 0, comment_count INTEGER NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY(board_id) REFERENCES boards(id), FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS post_media (id INTEGER PRIMARY KEY AUTOINCREMENT, post_id INTEGER NOT NULL, stored_name TEXT NOT NULL UNIQUE, mime_type TEXT NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, size_bytes INTEGER NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS post_tags (post_id INTEGER NOT NULL, tag TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(post_id, tag), FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS resource_media (id INTEGER PRIMARY KEY AUTOINCREMENT, resource_id INTEGER NOT NULL, stored_name TEXT NOT NULL UNIQUE, mime_type TEXT NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, size_bytes INTEGER NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, FOREIGN KEY(resource_id) REFERENCES resources(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS comments (id INTEGER PRIMARY KEY AUTOINCREMENT, post_id INTEGER NOT NULL, parent_id INTEGER, author_id INTEGER NOT NULL, content TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'published', created_at DATETIME NOT NULL, FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE, FOREIGN KEY(parent_id) REFERENCES comments(id) ON DELETE SET NULL, FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS comment_media (id INTEGER PRIMARY KEY AUTOINCREMENT, comment_id INTEGER NOT NULL, stored_name TEXT NOT NULL UNIQUE, mime_type TEXT NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, size_bytes INTEGER NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, FOREIGN KEY(comment_id) REFERENCES comments(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_users_status_created ON users(status, created_at);
CREATE INDEX IF NOT EXISTS idx_posts_status_updated ON posts(status, updated_at);
CREATE TABLE IF NOT EXISTS post_bookmarks (post_id INTEGER NOT NULL, user_id INTEGER NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (post_id, user_id));
CREATE TABLE IF NOT EXISTS post_reposts (post_id INTEGER NOT NULL, user_id INTEGER NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (post_id, user_id));
CREATE TABLE IF NOT EXISTS roblox_music_favorites (user_id INTEGER NOT NULL, asset_id INTEGER NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL, creator_name TEXT NOT NULL, thumbnail_url TEXT NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (user_id, asset_id));
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, actor_id INTEGER NOT NULL, kind TEXT NOT NULL, post_id INTEGER, comment_id INTEGER, conversation_id INTEGER, created_at DATETIME NOT NULL, read_at DATETIME, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE, FOREIGN KEY(comment_id) REFERENCES comments(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS conversation_invite_links (id INTEGER PRIMARY KEY AUTOINCREMENT, conversation_id INTEGER NOT NULL, token_hash TEXT NOT NULL UNIQUE, created_by INTEGER NOT NULL, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, revoked_at DATETIME, FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS wallet_topup_orders (id INTEGER PRIMARY KEY AUTOINCREMENT, order_no TEXT NOT NULL UNIQUE, user_id INTEGER NOT NULL, amount_cents INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', gateway_trade_no TEXT UNIQUE, paid_at DATETIME, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS wallet_ledgers (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, entry_type TEXT NOT NULL, amount_cents INTEGER NOT NULL, reference_type TEXT NOT NULL, reference_id INTEGER NOT NULL, note TEXT NOT NULL DEFAULT '', created_at DATETIME NOT NULL, UNIQUE(user_id, reference_type, reference_id, entry_type), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS avatar_frames (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', style TEXT NOT NULL DEFAULT 'ring', image_url TEXT NOT NULL DEFAULT '', primary_color TEXT NOT NULL DEFAULT '#1d9bf0', secondary_color TEXT NOT NULL DEFAULT '#8b5cf6', price_cents INTEGER NOT NULL DEFAULT 0, allowed_regular INTEGER NOT NULL DEFAULT 1, allowed_member INTEGER NOT NULL DEFAULT 1, allowed_admin INTEGER NOT NULL DEFAULT 1, enabled INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, sales_count INTEGER NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS user_avatar_frames (user_id INTEGER NOT NULL, frame_id INTEGER NOT NULL, price_paid_cents INTEGER NOT NULL, purchased_at DATETIME NOT NULL, PRIMARY KEY(user_id, frame_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(frame_id) REFERENCES avatar_frames(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS user_avatar_frame_equipment (user_id INTEGER PRIMARY KEY, frame_id INTEGER NOT NULL, equipped_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(frame_id) REFERENCES avatar_frames(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS avatar_frame_upload_settings (id INTEGER PRIMARY KEY, allow_regular_upload INTEGER NOT NULL DEFAULT 0, allow_member_upload INTEGER NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS avatar_frame_submissions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image_url TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', review_note TEXT NOT NULL DEFAULT '', reviewed_by INTEGER, reviewed_at DATETIME, approved_frame_id INTEGER, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(approved_frame_id) REFERENCES avatar_frames(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS redeem_codes (id INTEGER PRIMARY KEY AUTOINCREMENT, code_hash BLOB NOT NULL UNIQUE, code_hint TEXT NOT NULL, amount_cents INTEGER NOT NULL, expires_at DATETIME, redeemed_by INTEGER, redeemed_at DATETIME, revoked_at DATETIME, created_by INTEGER NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(redeemed_by) REFERENCES users(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS content_moderation_audits (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_id INTEGER, content_type TEXT NOT NULL, content_hash TEXT NOT NULL, decision TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', model TEXT NOT NULL, created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS notices (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, content TEXT NOT NULL, link_url TEXT NOT NULL DEFAULT '', level TEXT NOT NULL DEFAULT 'info', pinned INTEGER NOT NULL DEFAULT 0, enabled INTEGER NOT NULL DEFAULT 1, created_by INTEGER, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE INDEX IF NOT EXISTS idx_content_moderation_actor_created ON content_moderation_audits(actor_id, created_at);
CREATE INDEX IF NOT EXISTS idx_content_moderation_type_created ON content_moderation_audits(content_type, created_at);
CREATE TABLE IF NOT EXISTS oauth_settings (id INTEGER PRIMARY KEY AUTOINCREMENT, enabled INTEGER NOT NULL DEFAULT 0, provider_key TEXT NOT NULL UNIQUE DEFAULT 'oidc', provider_name TEXT NOT NULL DEFAULT 'OAuth', client_id TEXT NOT NULL DEFAULT '', client_secret_ciphertext TEXT NOT NULL, authorization_url TEXT NOT NULL DEFAULT '', token_url TEXT NOT NULL DEFAULT '', userinfo_url TEXT NOT NULL DEFAULT '', scopes TEXT NOT NULL DEFAULT 'openid email profile', token_auth_method TEXT NOT NULL DEFAULT 'client_secret_post', require_verified_email INTEGER NOT NULL DEFAULT 1, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS oauth_accounts (provider_key TEXT NOT NULL, subject TEXT NOT NULL, user_id INTEGER NOT NULL, created_at DATETIME NOT NULL, last_login_at DATETIME NOT NULL, PRIMARY KEY(provider_key, subject), UNIQUE(provider_key, user_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS oauth_login_states (state_hash BLOB PRIMARY KEY, code_verifier TEXT NOT NULL, provider_key TEXT NOT NULL DEFAULT 'oidc', return_to TEXT NOT NULL DEFAULT '/', expires_at DATETIME NOT NULL, created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS user_two_factor_settings (user_id INTEGER PRIMARY KEY, secret_ciphertext TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, confirmed_at DATETIME, updated_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS two_factor_login_challenges (token_hash BLOB PRIMARY KEY, user_id INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, expires_at DATETIME NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS point_accounts (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE, balance INTEGER NOT NULL DEFAULT 0, total_earned INTEGER NOT NULL DEFAULT 0, total_spent INTEGER NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS point_ledgers (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, amount INTEGER NOT NULL, entry_type TEXT NOT NULL, source_id INTEGER NOT NULL DEFAULT 0, balance_after INTEGER NOT NULL, note TEXT NOT NULL DEFAULT '', created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_point_ledgers_user_created ON point_ledgers(user_id, created_at, id);
CREATE TABLE IF NOT EXISTS point_products (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, image_url TEXT NOT NULL DEFAULT '', points_required INTEGER NOT NULL, shipping_points INTEGER NOT NULL DEFAULT 0, stock INTEGER NOT NULL, physical INTEGER NOT NULL DEFAULT 0, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft', sort_order INTEGER NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS point_orders (id INTEGER PRIMARY KEY AUTOINCREMENT, order_no TEXT NOT NULL UNIQUE, user_id INTEGER NOT NULL, product_id INTEGER NOT NULL, product_name TEXT NOT NULL, product_image TEXT NOT NULL DEFAULT '', points_spent INTEGER NOT NULL, shipping_points INTEGER NOT NULL DEFAULT 0, physical INTEGER NOT NULL DEFAULT 0, recipient_name TEXT NOT NULL DEFAULT '', recipient_phone TEXT NOT NULL DEFAULT '', address_json TEXT, carrier TEXT NOT NULL DEFAULT '', tracking_no TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', note TEXT NOT NULL DEFAULT '', ordered_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(product_id) REFERENCES point_products(id));
CREATE TABLE IF NOT EXISTS lottery_activities (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, cover_url TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', style TEXT NOT NULL DEFAULT 'wheel', cost_points INTEGER NOT NULL DEFAULT 0, daily_limit INTEGER NOT NULL DEFAULT 0, total_limit INTEGER NOT NULL DEFAULT 0, daily_free_attempts INTEGER NOT NULL DEFAULT 0, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, status TEXT NOT NULL DEFAULT 'draft', sort_order INTEGER NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS lottery_prizes (id INTEGER PRIMARY KEY AUTOINCREMENT, activity_id INTEGER NOT NULL, name TEXT NOT NULL, image_url TEXT NOT NULL DEFAULT '', probability_bp INTEGER NOT NULL, stock INTEGER NOT NULL, prize_type TEXT NOT NULL, bound_id INTEGER NOT NULL DEFAULT 0, config_json TEXT NOT NULL DEFAULT '{}', physical INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY(activity_id) REFERENCES lottery_activities(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS lottery_draws (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, activity_id INTEGER NOT NULL, prize_id INTEGER, points_charged INTEGER NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(activity_id) REFERENCES lottery_activities(id) ON DELETE CASCADE, FOREIGN KEY(prize_id) REFERENCES lottery_prizes(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS lottery_wins (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, activity_id INTEGER NOT NULL, prize_id INTEGER NOT NULL, prize_name TEXT NOT NULL, prize_type TEXT NOT NULL, physical INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending', order_id INTEGER, address_json TEXT, delivered_at DATETIME, won_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(activity_id) REFERENCES lottery_activities(id), FOREIGN KEY(prize_id) REFERENCES lottery_prizes(id), FOREIGN KEY(order_id) REFERENCES point_orders(id) ON DELETE SET NULL);
